def shortest_cycle_length(S, n):
    G = set()
    for s in S:
        G.add(s % n)
        G.add((-s) % n)
    G.discard(0)

    from collections import deque
    dist = {}
    q = deque()
    q.append((0, 0, -1))
    dist[0] = 0

    while q:
        v, d, p = q.popleft()
        for g in G:
            w = (v + g) % n
            if w == p:
                continue
            if w == 0 and d >= 2:
                return d + 1
            if w not in dist:
                dist[w] = d + 1
                q.append((w, d+1, v))
    return None

def test():
    from itertools import combinations
    n = 26
    for S_size in [2, 3]:
        print(f"\nSearching for S of size {S_size}:")
        found = []
        for S in combinations(range(1, 14), S_size):
            S = set(S)
            g = shortest_cycle_length(S, n)
            deg = 2 * len(S)
            if 13 in S:
                deg -= 1
            if g is not None and g >= 7:
                found.append((S, g, deg))
        print(f"Found {len(found)} sets")
        for S, g, deg in found[:10]:
            print(f"  S={S}, girth={g}, degree={deg}")

test()
